# add debug print of B array before replacements applied
awk '
function lvl(s,   c) {
  c = 0
  while (substr(s, c + 1, 1) == "#") c++
  if (c < 1 || c > 6 || substr(s, c + 1, 1) != " ") return 0
  return c
}
function htext(s,   t) { t = substr(s, lvl(s) + 2); sub(/[ \t\r]+$/, "", t); return t }
BEGIN { FENCE = "\140\140\140"; PFX = "Replace: "; WPFX = "Withdraw: " }
{ L[++n] = $0 }
END {
  for (i = 1; i <= n; i++) C[i] = L[i]
  m = n
  nb = 0; nr = 0; i = 1
  while (i <= m) {
    if (substr(C[i],1,3)=="## " && substr(htext(C[i]),1,length(WPFX))==WPFX) { i+=1 }
    else if (substr(C[i],1,3)=="## " && substr(htext(C[i]),1,length(PFX))==PFX) {
      T = substr(htext(C[i]), length(PFX)+1)
      print "MARKER at line " i ": Replace: " T
      j = i+1; h = (j<=m)?lvl(C[j]):0
      print "  j=" j " h=" h " content=[" C[j] "]"
      k = (j <= m && h != 1) ? j + 1 : j
      print "  k=" k
      while (k <= m && !(lvl(C[k]) >= 1 && lvl(C[k]) <= 2)) k++
      print "  final k=" k " content line k=[" (k<=m?C[k]:"EOF") "]"
      print "  captured content range: " j " to " (k-1)
      for (q=j;q<k;q++) print "    captured[" q "]=[" C[q] "]"
      i = k
    } else { B[++nb]=C[i]; i++ }
  }
  print "---B array (base content)---"
  for (i=1;i<=nb;i++) print "B[" i "]=[" B[i] "]"
}
' test.md

